import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"中孚","description":"焦氏易林注 - 中孚","frontmatter":{"title":"中孚","description":"焦氏易林注 - 中孚"},"headers":[],"relativePath":"classics/jiaoyilin/061.md","filePath":"classics/jiaoyilin/061.md"}'),l={name:"classics/jiaoyilin/061.md"};function n(d,a,t,s,o,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="中孚" tabindex="-1">中孚 <a class="header-anchor" href="#中孚" aria-label="Permalink to “中孚”">​</a></h1><h3 id="中孚-1" tabindex="-1">中孚 <a class="header-anchor" href="#中孚-1" aria-label="Permalink to “中孚”">​</a></h3><h3 id="中孚之乾" tabindex="-1">中孚之乾 <a class="header-anchor" href="#中孚之乾" aria-label="Permalink to “中孚之乾”">​</a></h3><h3 id="林辭" tabindex="-1">林辭 <a class="header-anchor" href="#林辭" aria-label="Permalink to “林辭”">​</a></h3><p>黃虹之野，賢君所在。管叔為相，國無災咎。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>此用《中孚》象。震為玄黃、為虹、為君，艮為野、為叔，《孝經援神契》黃虹抱曰輔臣納忠。《帝王世紀》少昊生，虹流華渚。《洛書》黃帝起，黃雲扶日。又《東方朔別傳》凡佔長吏下車，當視天有黃雲來覆車。震為竹，故曰管叔。艮為國。○叔，汲古作仲，非。中孚無仲象也，茲依宋元本。</p><h3 id="中孚之坤" tabindex="-1">中孚之坤 <a class="header-anchor" href="#中孚之坤" aria-label="Permalink to “中孚之坤”">​</a></h3><h3 id="林辭-1" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-1" aria-label="Permalink to “林辭”">​</a></h3><p>符左契右，相與合齒。乾坤利貞，乳生六子。長大成就，風言如母。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>詳《兌》之《大過》。宋元本石下多梁叔有若四字，斷為衍文，茲依汲古。</p><h3 id="中孚之屯" tabindex="-1">中孚之屯 <a class="header-anchor" href="#中孚之屯" aria-label="Permalink to “中孚之屯”">​</a></h3><h3 id="林辭-2" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-2" aria-label="Permalink to “林辭”">​</a></h3><p>蝗嚙我稻，驅不可去。實穗無有，但見空藳。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>詳《小畜》之《大壯》。</p><h3 id="中孚之蒙" tabindex="-1">中孚之蒙 <a class="header-anchor" href="#中孚之蒙" aria-label="Permalink to “中孚之蒙”">​</a></h3><h3 id="林辭-3" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-3" aria-label="Permalink to “林辭”">​</a></h3><p>嬰孩求乳，母歸其子，黃麑悅喜。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>詳《履》之《同人》。孩，元本作孫，依宋本。</p><h3 id="中孚之需" tabindex="-1">中孚之需 <a class="header-anchor" href="#中孚之需" aria-label="Permalink to “中孚之需”">​</a></h3><h3 id="林辭-4" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-4" aria-label="Permalink to “林辭”">​</a></h3><p>折若蔽目，不見稚叔。失旅亡民，遠去家室。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>詳《師》之《蒙》。第二句元本作父旅相逐，父乃失之訛。第四句元本作不見衛國，均依宋本、汲古。若，汲古作葉，非。</p><h3 id="中孚之訟" tabindex="-1">中孚之訟 <a class="header-anchor" href="#中孚之訟" aria-label="Permalink to “中孚之訟”">​</a></h3><h3 id="林辭-5" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-5" aria-label="Permalink to “林辭”">​</a></h3><p>牂羊羵首，君子不飽。年飢孔荒，士民危殆。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>《詩小雅》牂羊墳首，茲作羵。按：魯語雲土之怪曰羵，註：羵，羊雌雄未成者，亦作墳。然則羵墳古通用，是焦詩與毛詩異字，非訛字也。伏震為羊，羵，大也。乾為首、為大，故曰羵首。乾為君子，離虗，故不飽，故飢。乾為年，坎為民、為危殆。○牂，汲古作，從宋元本。羵，宋元本作肥，依汲古。</p><h3 id="中孚之師" tabindex="-1">中孚之師 <a class="header-anchor" href="#中孚之師" aria-label="Permalink to “中孚之師”">​</a></h3><h3 id="林辭-6" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-6" aria-label="Permalink to “林辭”">​</a></h3><p>靈龜陸處，盤桓失所。伊子退耕，桀亂無輔。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>詳《歸妹》之《剝》。</p><h3 id="中孚之比" tabindex="-1">中孚之比 <a class="header-anchor" href="#中孚之比" aria-label="Permalink to “中孚之比”">​</a></h3><h3 id="林辭-7" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-7" aria-label="Permalink to “林辭”">​</a></h3><p>威約拘囚，為人所誣。皋陶平理，幾得脫免。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>脫免，元本作免脫，依宋本、汲古。</p><h3 id="中孚之小畜" tabindex="-1">中孚之小畜 <a class="header-anchor" href="#中孚之小畜" aria-label="Permalink to “中孚之小畜”">​</a></h3><h3 id="林辭-8" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-8" aria-label="Permalink to “林辭”">​</a></h3><p>烏升鵲舉，照臨東海。尨降庭堅，為陶叔後。封於英六，福履綏厚。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>詳《需》之《大畜》。</p><h3 id="中孚之履" tabindex="-1">中孚之履 <a class="header-anchor" href="#中孚之履" aria-label="Permalink to “中孚之履”">​</a></h3><h3 id="林辭-9" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-9" aria-label="Permalink to “林辭”">​</a></h3><p>四目相視，稍近同軌。日昳之後，見吾伯姊。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>詳《益》之《需》。近，汲古作延，軌作執，均依宋元本。</p><h3 id="中孚之泰" tabindex="-1">中孚之泰 <a class="header-anchor" href="#中孚之泰" aria-label="Permalink to “中孚之泰”">​</a></h3><h3 id="林辭-10" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-10" aria-label="Permalink to “林辭”">​</a></h3><p>大步上車，南至喜家。送我狐裘，與福載來。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>詳《節》之《觀》。</p><h3 id="中孚之否" tabindex="-1">中孚之否 <a class="header-anchor" href="#中孚之否" aria-label="Permalink to “中孚之否”">​</a></h3><h3 id="林辭-11" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-11" aria-label="Permalink to “林辭”">​</a></h3><p>穿都相合，未敢面見。媒妁無良，使我不鄉。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>坤為都。穿，元本作卒，相作和，鄉作香，均依汲古，然義皆難解，恐仍有訛字。</p><h3 id="中孚之同人" tabindex="-1">中孚之同人 <a class="header-anchor" href="#中孚之同人" aria-label="Permalink to “中孚之同人”">​</a></h3><h3 id="林辭-12" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-12" aria-label="Permalink to “林辭”">​</a></h3><p>鴻飛遵陸，公出不復，伯氏客宿。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>詳《剝》之《升》。出，汲古作母，依宋元本。</p><h3 id="中孚之大有" tabindex="-1">中孚之大有 <a class="header-anchor" href="#中孚之大有" aria-label="Permalink to “中孚之大有”">​</a></h3><h3 id="林辭-13" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-13" aria-label="Permalink to “林辭”">​</a></h3><p>代戍失期，患生無知。懼以發難，為我開基，邦國憂愁。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>《左傳莊八年》齊侯使連稱管至父戍葵丘，瓜時而往，曰及瓜而代，期戍，公問不至，故與無知等作亂。伏艮為守、為戍、為期，坎為失，故曰失期。坎為患、為憂懼，坤為我、為邦國，全用旁通。○生，汲古作至，依宋元本。知，各本皆作聊，依《漸》之《謙》校。</p><h3 id="中孚之謙" tabindex="-1">中孚之謙 <a class="header-anchor" href="#中孚之謙" aria-label="Permalink to “中孚之謙”">​</a></h3><h3 id="林辭-14" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-14" aria-label="Permalink to “林辭”">​</a></h3><p>伯氏爭言，戰於龍門。構怨結禍，三世不安。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>詳《坤》之《離》。正反震相背，故爭言。震為伯，故曰伯氏。○伯氏，宋元本作齊魯，茲依汲古。</p><h3 id="中孚之豫" tabindex="-1">中孚之豫 <a class="header-anchor" href="#中孚之豫" aria-label="Permalink to “中孚之豫”">​</a></h3><h3 id="林辭-15" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-15" aria-label="Permalink to “林辭”">​</a></h3><p>周政養賊，背生人足。陸行不安，國危為患。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>震為周，坎為賊，坤為政、為育，故曰周政養賊。震為足，艮為背，足在背上，故曰背生人足。坤為陸，坎險，故不安。坤為國，坎為患也。此全用卦象制辭，未必有故實。○賊，宋元本作賤，茲依汲古。</p><h3 id="中孚之隨" tabindex="-1">中孚之隨 <a class="header-anchor" href="#中孚之隨" aria-label="Permalink to “中孚之隨”">​</a></h3><h3 id="林辭-16" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-16" aria-label="Permalink to “林辭”">​</a></h3><p>蜩螗歡喜，草木暢茂。百果蕃生，日益富有。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>詳《謙》之《解》。喜，宋元本作翹，富作多，依汲古。</p><h3 id="中孚之蠱" tabindex="-1">中孚之蠱 <a class="header-anchor" href="#中孚之蠱" aria-label="Permalink to “中孚之蠱”">​</a></h3><h3 id="林辭-17" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-17" aria-label="Permalink to “林辭”">​</a></h3><p>魃為災虐，風吹雲卻。止不得復，復歸其宅。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>首句汲古作薄災暴虎，宋元本作薄災暴虐，依《小畜》之《中孚》校。薄為魃之音訛字。</p><h3 id="中孚之臨" tabindex="-1">中孚之臨 <a class="header-anchor" href="#中孚之臨" aria-label="Permalink to “中孚之臨”">​</a></h3><h3 id="林辭-18" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-18" aria-label="Permalink to “林辭”">​</a></h3><p>乘騮駕驪，遊至東齊。遭遇行旅，逆我以資，厚得利歸。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>震為馬，坤亦為馬，故曰乘騮駕驪。震為東，伏巽為齊，故曰東齊。震為行旅，坤為資財，逆行，故曰逆我以資。坤多，故曰厚得利。</p><h3 id="中孚之觀" tabindex="-1">中孚之觀 <a class="header-anchor" href="#中孚之觀" aria-label="Permalink to “中孚之觀”">​</a></h3><h3 id="林辭-19" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-19" aria-label="Permalink to “林辭”">​</a></h3><p>鳳生七子，同巢共乳，歡悅相保。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>坤文，故曰鳳。艮數七，故曰七子。艮為巢、為乳，伏震為歡悅。</p><h3 id="中孚之噬嗑" tabindex="-1">中孚之噬嗑 <a class="header-anchor" href="#中孚之噬嗑" aria-label="Permalink to “中孚之噬嗑”">​</a></h3><h3 id="林辭-20" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-20" aria-label="Permalink to “林辭”">​</a></h3><p>桃雀竊脂，巢於小枝。動搖不安，為風所吹。心寒漂搖，常憂殆危。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>詳《損》之《渙》。</p><h3 id="中孚之賁" tabindex="-1">中孚之賁 <a class="header-anchor" href="#中孚之賁" aria-label="Permalink to “中孚之賁”">​</a></h3><h3 id="林辭-21" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-21" aria-label="Permalink to “林辭”">​</a></h3><p>東山西山，各自止安。雖相登望，竟未同堂。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>詳《姤》之《坤》。竟未，汲古作不得，依宋元本。</p><h3 id="中孚之剝" tabindex="-1">中孚之剝 <a class="header-anchor" href="#中孚之剝" aria-label="Permalink to “中孚之剝”">​</a></h3><h3 id="林辭-22" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-22" aria-label="Permalink to “林辭”">​</a></h3><p>匍匐出走，驚懼惶恐。白虎生孫，蓐收在後。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>匍匐，以手行也。艮為手，手在地上，故曰匍匐。陽在上，故曰出。坤為恐懼，艮為虎、為孫，伏兌為西方，色白，故曰白虎。兌為秋，故曰蓐收。《月令》孟秋之月其神蓐收是也。○匐，宋元本作伏，依汲古。惶，宋本、汲古作皇，依元本。</p><h3 id="中孚之復" tabindex="-1">中孚之復 <a class="header-anchor" href="#中孚之復" aria-label="Permalink to “中孚之復”">​</a></h3><h3 id="林辭-23" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-23" aria-label="Permalink to “林辭”">​</a></h3><p>重弋射隼，不知所定。質疑蓍龜，告以肥牡。明神答報，宜利止居。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>詳《困》之《蹇》。弋，元本訛或，牡作性，依宋本、汲古。四五句宋元本倒，依汲古。</p><h3 id="中孚之無妄" tabindex="-1">中孚之無妄 <a class="header-anchor" href="#中孚之無妄" aria-label="Permalink to “中孚之無妄”">​</a></h3><h3 id="林辭-24" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-24" aria-label="Permalink to “林辭”">​</a></h3><p>開門內福，喜至我側。加以善祥，為吾室宅。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>宮城洛邑，以昭文德。震為開，艮為門，上乾，故曰納福。震為喜、為善祥，艮為室宅、為宮城、為邑，乾為王，故曰洛邑。洛邑，王城也。伏坤為文。○加以，宋元本作嘉門，依汲古。室，汲古作家，昭作招，依宋元本。</p><h3 id="中孚之大畜" tabindex="-1">中孚之大畜 <a class="header-anchor" href="#中孚之大畜" aria-label="Permalink to “中孚之大畜”">​</a></h3><h3 id="林辭-25" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-25" aria-label="Permalink to “林辭”">​</a></h3><p>鳥飛狐鳴，國亂不寧。下強上弱，為陰所刑。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>艮為鳥、為狐，震為飛、為鳴，故曰鳥飛狐鳴。艮為國，兌毀，故曰不寧。四五陰爻，乾為艮所畜，故曰為陰所刑。</p><h3 id="中孚之頤" tabindex="-1">中孚之頤 <a class="header-anchor" href="#中孚之頤" aria-label="Permalink to “中孚之頤”">​</a></h3><h3 id="林辭-26" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-26" aria-label="Permalink to “林辭”">​</a></h3><p>三雞啄粟，八雛從食。飢鷹卒擊，失亡兩叔。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>伏巽為雞，震數三，故曰三雞。伏兌為啄。巽為粟，震為雛，坤數八，故曰八雛。震為從、為食，艮為鷹，坤虗，故曰飢鷹。艮為擊、為叔，坤數二，坤喪，故曰失亡兩叔。</p><h3 id="中孚之大過" tabindex="-1">中孚之大過 <a class="header-anchor" href="#中孚之大過" aria-label="Permalink to “中孚之大過”">​</a></h3><h3 id="林辭-27" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-27" aria-label="Permalink to “林辭”">​</a></h3><p>嘆息不悅，憂從中出。喪我金罌，無妄失位。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>兌口，故曰嘆息。互大坎，故不悅，故憂從中出。乾為金，震為罌，震伏，故曰喪我金罌。○罌，宋元本作嬰，依汲古。從，汲古作逆，依宋元本。</p><h3 id="中孚之坎" tabindex="-1">中孚之坎 <a class="header-anchor" href="#中孚之坎" aria-label="Permalink to “中孚之坎”">​</a></h3><h3 id="林辭-28" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-28" aria-label="Permalink to “林辭”">​</a></h3><p>剛柔相呼，二姓為家。霜降既同，惠我以仁。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>詳《家人》之《損》。二，宋元本作三，依汲古。</p><h3 id="中孚之離" tabindex="-1">中孚之離 <a class="header-anchor" href="#中孚之離" aria-label="Permalink to “中孚之離”">​</a></h3><h3 id="林辭-29" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-29" aria-label="Permalink to “林辭”">​</a></h3><p>襄送季女，至於盪道。齊子旦夕，留連久處。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》之《大過》。末句元本作久流連處，依宋本、汲古。襄送，各本多作送我，依《屯》之《大過》校。</p><h3 id="中孚之鹹" tabindex="-1">中孚之鹹 <a class="header-anchor" href="#中孚之鹹" aria-label="Permalink to “中孚之鹹”">​</a></h3><h3 id="林辭-30" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-30" aria-label="Permalink to “林辭”">​</a></h3><p>低頭竊視，有所畏避。行作不利，酒酢魚餒，眾莫貪嗜。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>艮為頭，澤下，故曰低頭。艮為視，巽為盜，故曰竊視。巽伏，故曰畏避。兌毀，故不利。兌為澤、為酒，巽為魚、為木，木作酸，故曰酒酢。酢，酸也。巽為爛，故曰餒。餒，爛也。○畏，宋元本作遇，依汲古。酢，宋本、汲古作酸。餒，汲古作敗，依元本及宋元本。</p><h3 id="中孚之恆" tabindex="-1">中孚之恆 <a class="header-anchor" href="#中孚之恆" aria-label="Permalink to “中孚之恆”">​</a></h3><h3 id="林辭-31" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-31" aria-label="Permalink to “林辭”">​</a></h3><p>典冊法書，藏閣蘭臺。雖遭亂潰，獨不遇災。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>詳《坤》之《大畜》。閣，汲古作在，依宋元本。</p><h3 id="中孚之遯" tabindex="-1">中孚之遯 <a class="header-anchor" href="#中孚之遯" aria-label="Permalink to “中孚之遯”">​</a></h3><h3 id="林辭-32" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-32" aria-label="Permalink to “林辭”">​</a></h3><p>旦醉病酒，暮即瘳愈，獨不及咎。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>伏震為旦，坤迷，故曰旦醉。○即，宋元本作多，末句作不反為咎，均依汲古。</p><h3 id="中孚之大壯" tabindex="-1">中孚之大壯 <a class="header-anchor" href="#中孚之大壯" aria-label="Permalink to “中孚之大壯”">​</a></h3><h3 id="林辭-33" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-33" aria-label="Permalink to “林辭”">​</a></h3><p>畫龍頭頸，文章未成。甘言美語，說辭無名。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>詳《蒙》之《噬嗑》。</p><h3 id="中孚之晉" tabindex="-1">中孚之晉 <a class="header-anchor" href="#中孚之晉" aria-label="Permalink to “中孚之晉”">​</a></h3><h3 id="林辭-34" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-34" aria-label="Permalink to “林辭”">​</a></h3><p>日月運行，一寒一暑。榮寵赫赫，不可得保。顛躓殞墮，更為士伍。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>詳《巽》之《震》。</p><h3 id="中孚之明夷" tabindex="-1">中孚之明夷 <a class="header-anchor" href="#中孚之明夷" aria-label="Permalink to “中孚之明夷”">​</a></h3><h3 id="林辭-35" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-35" aria-label="Permalink to “林辭”">​</a></h3><p>爭利王市，朝多君子。蘇氏六國，獲其榮寵。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>伏巽為利市，震君，故曰王市。坤為朝，震為君子、為蘇，坤為國，坎卦數六，故曰六國。言蘇秦說六國，佩六國相印也。</p><h3 id="中孚之家人" tabindex="-1">中孚之家人 <a class="header-anchor" href="#中孚之家人" aria-label="Permalink to “中孚之家人”">​</a></h3><h3 id="林辭-36" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-36" aria-label="Permalink to “林辭”">​</a></h3><p>六蛇奔走，俱入茂草。驚於長途，畏懼啄口。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>詳《豐》之《巽》。</p><h3 id="中孚之睽" tabindex="-1">中孚之睽 <a class="header-anchor" href="#中孚之睽" aria-label="Permalink to “中孚之睽”">​</a></h3><h3 id="林辭-37" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-37" aria-label="Permalink to “林辭”">​</a></h3><p>懸貆素餐，食非其任。失輿剝廬，休坐徙居。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>詳《頤》之《益》。</p><h3 id="中孚之蹇" tabindex="-1">中孚之蹇 <a class="header-anchor" href="#中孚之蹇" aria-label="Permalink to “中孚之蹇”">​</a></h3><h3 id="林辭-38" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-38" aria-label="Permalink to “林辭”">​</a></h3><p>歡欣九子，俱見大喜。提攜福至，王孫是富。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>此用《中孚》象。震為歡欣，數九，故曰九子。艮手為提攜、為孫，震君，故曰王孫。○至，元本作善，依汲古。</p><h3 id="中孚之解" tabindex="-1">中孚之解 <a class="header-anchor" href="#中孚之解" aria-label="Permalink to “中孚之解”">​</a></h3><h3 id="林辭-39" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-39" aria-label="Permalink to “林辭”">​</a></h3><p>伯夷叔齊，貞廉之師。以德防患，憂禍不存。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>詳《革》之《否》。</p><h3 id="中孚之損" tabindex="-1">中孚之損 <a class="header-anchor" href="#中孚之損" aria-label="Permalink to “中孚之損”">​</a></h3><h3 id="林辭-40" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-40" aria-label="Permalink to “林辭”">​</a></h3><p>雄聖伏名，人匿麟驚。走鳳飛北，亂潰未息。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>詳《否》之《大過》。</p><h3 id="中孚之益" tabindex="-1">中孚之益 <a class="header-anchor" href="#中孚之益" aria-label="Permalink to “中孚之益”">​</a></h3><h3 id="林辭-41" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-41" aria-label="Permalink to “林辭”">​</a></h3><p>久鰥無偶，思配織女。求其非望，自令寡居。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>艮為鰥，坤女，巽為繩、為織，故曰織女。艮為求、為望，巽為寡，言織女為天孫不能求也。</p><h3 id="中孚之夬" tabindex="-1">中孚之夬 <a class="header-anchor" href="#中孚之夬" aria-label="Permalink to “中孚之夬”">​</a></h3><h3 id="林辭-42" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-42" aria-label="Permalink to “林辭”">​</a></h3><p>破亡之國，天所不福，難以止息。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>兌為破，坤為國，坤伏不見，故曰天所不福。乾為天。</p><h3 id="中孚之姤" tabindex="-1">中孚之姤 <a class="header-anchor" href="#中孚之姤" aria-label="Permalink to “中孚之姤”">​</a></h3><h3 id="林辭-43" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-43" aria-label="Permalink to “林辭”">​</a></h3><p>老慵多卻，弊政為賊。阿房驪山，子嬰失國。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>伏坤為老，坤柔，故曰老慵。巽為隙，卻隙同。巽伏為賊，坤為弊、為政，故曰弊政為賊。中孚艮為房、為山，震馬，故曰驪山。艮少，故曰子嬰。○卻，汲古訛欲，依宋元本。</p><h3 id="中孚之萃" tabindex="-1">中孚之萃 <a class="header-anchor" href="#中孚之萃" aria-label="Permalink to “中孚之萃”">​</a></h3><h3 id="林辭-44" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-44" aria-label="Permalink to “林辭”">​</a></h3><p>三羖六牂，相隨俱行。迷入空澤，經涉虎廬。為所傷賊，死於牙腹。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>詳《同人》之《蒙》。經，元本作遙，依汲古。</p><h3 id="中孚之升" tabindex="-1">中孚之升 <a class="header-anchor" href="#中孚之升" aria-label="Permalink to “中孚之升”">​</a></h3><h3 id="林辭-45" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-45" aria-label="Permalink to “林辭”">​</a></h3><p>喋囁噱嚾，昧冥相摶。多言少實，語無成事。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>震言，正反兌亦為言，故曰喋囁。喋囁，多言也。震為笑樂，故曰噱嚾。噱，大笑。嚾，音歡。喧囂也。坤為黑，故曰昧冥。伏艮為摶，正反艮，故曰相摶。正反兌，故曰多言。坤虛，故曰少實，語無成事。坤為事。○喋，宋本訛囁，汲古訛噬，茲依元本。噱嚾，宋元本訛處懼，依汲古。噱，汲古訛作，於是宋元本又由而竟作處矣，以此證汲古所據之，本前於宋元。嚾，汲古《明夷》之《豫》、《謙》之《豫》、《謙》之《乾》皆訛為耀，獨此處存其真，而宋元本則訛為懼。《明夷》之《豫》、《謙》之《乾》則又皆訛為曜，於此見汲古本之可貴也。摶，各本皆作搏，然與嚾不韻，故決其為摶字，以摶與搏形太近也，且《明夷》之《豫》宋本作傳，尤為作摶確證。</p><h3 id="中孚之困" tabindex="-1">中孚之困 <a class="header-anchor" href="#中孚之困" aria-label="Permalink to “中孚之困”">​</a></h3><h3 id="林辭-46" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-46" aria-label="Permalink to “林辭”">​</a></h3><p>舞陽漸離，擊築善歌。慕丹之義，為燕助軻。陰謀不遂，矐目死亡，功名何施。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>《史記刺客傳》荊軻奉樊於期首函，秦舞陽奉地圖，及事敗，秦人大索太子丹及荊卿之客，高漸離善擊築，秦王乃矐其目，使擊築於側，後以鉛實築中擊秦王，乃被殺。伏震為舞、為築、為歌，艮手為擊，故曰擊築善歌。坎赤，故曰丹。兌為燕，震為軻，故曰為燕助軻。坎為陰謀，離為目，坎為失，故曰矐目。矐，《索隱》曰以馬矢燻目，令失明也。坎為棺槨，故曰死亡。震為功，艮為名，艮震皆伏，故曰功名何施。○舞，宋元本作武，依汲古。矐，汲古作霍，依宋元本。目，宋元本作自，何作賈，均依汲古。助，汲古作荊，依宋元本。</p><h3 id="中孚之井" tabindex="-1">中孚之井 <a class="header-anchor" href="#中孚之井" aria-label="Permalink to “中孚之井”">​</a></h3><h3 id="林辭-47" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-47" aria-label="Permalink to “林辭”">​</a></h3><p>尹氏伯奇，父子分離。無罪被辜，長舌為災。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>詳《訟》之《大有》。</p><h3 id="中孚之革" tabindex="-1">中孚之革 <a class="header-anchor" href="#中孚之革" aria-label="Permalink to “中孚之革”">​</a></h3><h3 id="林辭-48" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-48" aria-label="Permalink to “林辭”">​</a></h3><p>五精亂行，政逆皇恩。湯武赫怒，共伐我域。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>《東京賦》辨方位而正，則五精帥而來摧，註：五精，五方星也。伏艮為星，坤為亂，震為行，故曰五精亂行。伏坤為政，坤逆行，故曰政逆皇恩，為怠遑訛字。《詩商頌》不敢怠遑，《箋》：怠惰，遑暇也。怠遑，言怠惰敖嬉也。坤柔，故曰怠遑。震為王，故曰湯武。震為怒、為伐，坤為域，全用旁通象。</p><h3 id="中孚之鼎" tabindex="-1">中孚之鼎 <a class="header-anchor" href="#中孚之鼎" aria-label="Permalink to “中孚之鼎”">​</a></h3><h3 id="林辭-49" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-49" aria-label="Permalink to “林辭”">​</a></h3><p>西厯玉山，東入玉門。登上福堂，飲萬歲漿。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>通《屯》。坎位西，震為玉，互艮，故曰玉山，故曰玉門，震為東也。震為登、為福，艮為堂，坤為萬歲、為漿，震口，故曰飲萬歲漿。</p><h3 id="中孚之震" tabindex="-1">中孚之震 <a class="header-anchor" href="#中孚之震" aria-label="Permalink to “中孚之震”">​</a></h3><h3 id="林辭-50" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-50" aria-label="Permalink to “林辭”">​</a></h3><p>行觸大忌，與司命忤。執囚束縛，拘制於吏，幽人有喜。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>震為行，坎為忌諱。諱，避也。坎隱，故曰忌。伏巽為命，坎為忤，故與司令忤。艮為執囚、為枸制，伏巽為束縛，艮為官吏、為幽人，震為喜。○大忌，宋本作夫忌，元本作天忌，汲古作忌諱，依《剝》林校，因夫天皆大之訛，故知決為大字。忤，宋元本作牾，似為啎之訛字，茲依汲古。</p><h3 id="中孚之艮" tabindex="-1">中孚之艮 <a class="header-anchor" href="#中孚之艮" aria-label="Permalink to “中孚之艮”">​</a></h3><h3 id="林辭-51" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-51" aria-label="Permalink to “林辭”">​</a></h3><p>機父不賢，朝多讒臣。君失其政，保家久貧。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>機疑為皇之訛，《詩小雅》皇父卿士，讒口囂囂。林似本此。艮初至五正反震，故曰讒。互震為君，艮為臣，坎為失，保疑為使之訛。○家，汲古作我，依宋元本。艮為家。</p><h3 id="中孚之漸" tabindex="-1">中孚之漸 <a class="header-anchor" href="#中孚之漸" aria-label="Permalink to “中孚之漸”">​</a></h3><h3 id="林辭-52" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-52" aria-label="Permalink to “林辭”">​</a></h3><p>三人俱行，北求大牂。長孟病足，倩季負糧。柳下之寶，不失我邦。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>詳《大有》之《豐》。不失我邦者，按：《家語》齊求岑鼎於魯，魯與鼎，齊侯曰：柳下季謂是則受之，魯侯請季，季曰：與齊鼎，求免君國也。但臣亦有國，免君之國，破臣之國，亦君之所惡也。魯乃以真鼎往。此林屢見，皆作驪黃，惟此作我邦，於事獨切。長孟，汲古作孟長，依宋元本。邦，宋元本作糧，亦後人所改，以求葉韻，獨汲古於此字存其真。負糧，依《革》之《恆》校，各本皆作囊。漸下艮為季、為負，上巽為糧，事詳《革》之《恆》。</p><h3 id="中孚之歸妹" tabindex="-1">中孚之歸妹 <a class="header-anchor" href="#中孚之歸妹" aria-label="Permalink to “中孚之歸妹”">​</a></h3><h3 id="林辭-53" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-53" aria-label="Permalink to “林辭”">​</a></h3><p>鵠思其雄，欲隨鳳東。順理羽翼，出次須日。中留北邑，復返其室。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>詳《需》之《離》。須日中，汲古作日中須，依宋元本。</p><h3 id="中孚之豐" tabindex="-1">中孚之豐 <a class="header-anchor" href="#中孚之豐" aria-label="Permalink to “中孚之豐”">​</a></h3><h3 id="林辭-54" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-54" aria-label="Permalink to “林辭”">​</a></h3><p>常德自如，不逢禍災。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>離為禍災。</p><h3 id="中孚之旅" tabindex="-1">中孚之旅 <a class="header-anchor" href="#中孚之旅" aria-label="Permalink to “中孚之旅”">​</a></h3><h3 id="林辭-55" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-55" aria-label="Permalink to “林辭”">​</a></h3><p>白鵠遊望，君子以寧。履德不愆，福祿來成。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>互巽為白，艮為鵠、為望，故曰白鵠遊望。艮為君子，艮安，故曰寧伏。震為履、為福祿。</p><h3 id="中孚之巽" tabindex="-1">中孚之巽 <a class="header-anchor" href="#中孚之巽" aria-label="Permalink to “中孚之巽”">​</a></h3><h3 id="林辭-56" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-56" aria-label="Permalink to “林辭”">​</a></h3><p>膚敏之德，發憤晨食。虜豹禽說，為王得福。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>詳《大有》之《困》。晨，汲古作忘，說作越，皆非。</p><h3 id="中孚之兌" tabindex="-1">中孚之兌 <a class="header-anchor" href="#中孚之兌" aria-label="Permalink to “中孚之兌”">​</a></h3><h3 id="林辭-57" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-57" aria-label="Permalink to “林辭”">​</a></h3><p>百足俱行，相輔為強。三聖翼事，王室寵光。國富民康。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》之《履》。宋元本無第四句，依汲古。</p><h3 id="中孚之渙" tabindex="-1">中孚之渙 <a class="header-anchor" href="#中孚之渙" aria-label="Permalink to “中孚之渙”">​</a></h3><h3 id="林辭-58" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-58" aria-label="Permalink to “林辭”">​</a></h3><p>生不逢時，困且多憂。年老衰極，中心悲愁。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>艮為時，震為生，下坎，故曰困且多憂。艮為壽，故曰年老。坎為中心、為悲愁。</p><h3 id="中孚之節" tabindex="-1">中孚之節 <a class="header-anchor" href="#中孚之節" aria-label="Permalink to “中孚之節”">​</a></h3><h3 id="林辭-59" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-59" aria-label="Permalink to “林辭”">​</a></h3><p>出門蹉跌，看道後旅。買羊逸亡，取物逃走。空手握拳，坐恨為咎。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>艮為門，震為出，坎蹇，故曰蹉跌。震為大塗、為後，兌為羊，與震連體，故曰逸亡。艮為手，正反艮相對，故曰空手握拳。坎為恨。</p><h3 id="中孚之中孚" tabindex="-1">中孚之中孚 <a class="header-anchor" href="#中孚之中孚" aria-label="Permalink to “中孚之中孚”">​</a></h3><h3 id="林辭-60" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-60" aria-label="Permalink to “林辭”">​</a></h3><p>鳥鳴嘻嘻，天火將下。燔我屋室，災及姤後。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>詳《兌》之《革》。鳥鳴，宋元本作烏鳥，依汲古。嘻嘻，汲古作喈喈，茲依宋元本。</p><h3 id="中孚之小過" tabindex="-1">中孚之小過 <a class="header-anchor" href="#中孚之小過" aria-label="Permalink to “中孚之小過”">​</a></h3><h3 id="林辭-61" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-61" aria-label="Permalink to “林辭”">​</a></h3><p>牧羊稻田，聞虎喧歡。畏懼悚惕，終無禍患。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>詳《隨》之《漸》。</p><h3 id="中孚之既濟" tabindex="-1">中孚之既濟 <a class="header-anchor" href="#中孚之既濟" aria-label="Permalink to “中孚之既濟”">​</a></h3><h3 id="林辭-62" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-62" aria-label="Permalink to “林辭”">​</a></h3><p>龍潛鳳北，箕子變服。陰孽萌作。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>北，汲古作池，依宋元本。箕，宋元本作其，依汲古。其子與蜀才讀同，且其箕音同，非訛字，不過他林皆作箕，故從汲古。</p><h3 id="中孚之未濟" tabindex="-1">中孚之未濟 <a class="header-anchor" href="#中孚之未濟" aria-label="Permalink to “中孚之未濟”">​</a></h3><h3 id="林辭-63" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-63" aria-label="Permalink to “林辭”">​</a></h3><p>國無比鄰，相與爭強。紛紛匈匈，天下擾攘。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>○匈匈，汲古作兇兇，依宋元本。攘，宋元本作憂，依汲古。</p>',322)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
